  it('emits Phase-0 distinct stage durations and a correlated turn summary for a business-read turn', async () => {
    const { prisma } = makePrisma();
    const { useCase } = makeUseCase(prisma, {
      permissions: ['line.ai.query'],
      intakeRouteFn: () => ({ status: 'ROUTED', intent: 'BUSINESS_READ_QUESTION', language: 'th', confidence: 0.9 }),
      aiGatewayFn: () => ({
        requestId: 'req-ai',
        replyText: 'ยอดขายวันนี้ 1,000 บาท',
        sourceRefs: [], sourceLabels: [], webLinks: [],
        intent: 'read_summary', agent: 'sales', refused: false,
        toolsInvoked: ['sales.get_sales_summary'],
        toolCalls: [{ name: 'sales.get_sales_summary', status: 'ok', durationMs: 12 }],
        modelCallCount: 3,
        modelLineage: [{ provider: 'bedrock', modelId: 'apac.anthropic.claude-3-5-sonnet-20241022-v2:0', region: 'ap-southeast-1', purpose: 'employee_line_assistant' }],
        usage: [{ tag: 't', modelId: 'apac.anthropic.claude-3-haiku-20240307-v1:0', ok: true, inputTokens: 100, outputTokens: 40, cacheReadInputTokens: 0, cacheWriteInputTokens: 0, durationMs: 5 }],
        durationMs: 20,
      }),
    });
    const logs: any[] = [];
    (useCase as any).logger = { log: (entry: any) => logs.push(entry), warn: () => undefined, error: () => undefined };

    await useCase.execute({ ...BASE_EVENT, webhookEventId: 'evt-trace-1', messageText: 'ยอดขายวันนี้เท่าไหร่' });

    // Distinct stage durations for the seams THIS API process observes — not lumped into dispatch.
    const stages = logs.filter((entry) => entry.msg === 'line.ai.stage');
    for (const stage of ['intake_route', 'gateway_turn', 'render', 'persistence', 'line_delivery']) {
      const event = stages.find((entry) => entry.stage === stage);
      assert.ok(event, `stage ${stage} emitted`);
      assert.equal(event.webhookEventId, 'evt-trace-1');
      assert.ok(Number.isInteger(event.durationMs) && event.durationMs >= 0, `${stage} has a numeric duration`);
    }
    // A business-read turn runs no capture and this release creates no reimbursement, so neither
    // may report a duration for work that never happened.
    assert.equal(stages.some((entry) => entry.stage === 'capture_execute' || entry.stage === 'reimbursement_execute'), false);

    // One correlated turn summary; every field is the ACTUAL value or an explicit null (nothing invented).
    const summary = logs.find((entry) => entry.msg === 'line.ai.turn_summary');
    assert.ok(summary, 'turn summary emitted');
    assert.equal(summary.webhookEventId, 'evt-trace-1');
    assert.ok(typeof summary.requestId === 'string' && summary.requestId.length > 0);
    assert.equal(summary.preparedPlanVersion, null, 'Phase 2: no producer, so null (not invented)');
    assert.equal(summary.lane, 'other', 'no prepared plan, no planner/compose call and no semantic coverage: neither the prepared nor the semantic lane');
    assert.equal(summary.intent, 'read_summary');
    assert.equal(summary.refused, false);
    assert.equal(summary.modelCallCount, 3);
    assert.equal(summary.toolCallCount, 1);
    assert.equal(summary.deliveryResult, 'ok');
    assert.equal(summary.usageInputTokens, 100);
    assert.equal(summary.usageOutputTokens, 40);
    assert.equal(summary.costSatang, null, 'cost is priced at settle time and stored per call in AiUsageEvent → null here, not re-priced');
    // Actual model identity derived from lineage + usage (deduped), not invented.
    assert.equal(summary.modelProvider, 'bedrock');
    assert.deepEqual([...summary.modelIds].sort(), ['apac.anthropic.claude-3-5-sonnet-20241022-v2:0', 'apac.anthropic.claude-3-haiku-20240307-v1:0']);
    // fallback is a distinct field, never conflated with refusal/error: no semantic coverage → null.
    assert.equal(summary.fallbackReason, null);

    // No raw message text or LINE user id in any trace event.
    for (const event of [...stages, summary]) {
      const keys = Object.keys(event);
      assert.ok(!keys.includes('lineUserId') && !keys.includes('messageText') && !keys.includes('text'), 'no raw identifiers/text');
    }
  });

  it('derives the turn summary lane and fallback reason from what the gateway turn response carries', async () => {
    const prepared = parseLineAiPreparedPlan({
      version: 1, complexity: 'simple', confidence: 0.9, responseMode: 'simple_grounded', answerShape: 'single_metric',
      intentPlan: {
        status: 'ROUTABLE', language: 'th', requiresHumanReview: false, refusals: [],
        intents: [{ intent: 'read_summary', subject: 'sale', agent: 'sales', priority: 1, requiredTools: ['sales.get_sales_summary'], missingContext: [] }],
      },
      proposedCalls: [{ toolName: 'sales.get_sales_summary', input: {} }],
    });
    assert.ok(prepared, 'prepared-plan fixture parses');
    const usageEntry = (tag: string) => ({ tag, modelId: 'global.anthropic.claude-sonnet-4-6', ok: true, inputTokens: 10, outputTokens: 5,
      cacheReadInputTokens: 0, cacheWriteInputTokens: 0, durationMs: 5 });
    const summaryFor = async (webhookEventId: string, options: { preparedPlan?: boolean; usage: unknown[]; semanticCoverage?: unknown[] }) => {
      const { prisma } = makePrisma();
      const { useCase } = makeUseCase(prisma, {
        permissions: ['line.ai.query'],
        config: { lineAiPreparedSimpleReadEnabled: true },
        intakeRouteFn: () => ({ status: 'ROUTED', intent: 'BUSINESS_READ_QUESTION', language: 'th', confidence: 0.9,
          ...(options.preparedPlan ? { preparedPlan: prepared } : {}) }),
        aiGatewayFn: () => ({
          requestId: 'req-ai', replyText: 'ยอดขายวันนี้ 1,000 บาท', sourceRefs: [], sourceLabels: [], webLinks: [],
          intent: 'read_summary', agent: 'sales', refused: false, toolsInvoked: [], toolCalls: [],
          modelLineage: [], usage: options.usage, durationMs: 10,
          ...(options.semanticCoverage ? { semanticCoverage: options.semanticCoverage } : {}),
        }),
      });
      const logs: any[] = [];
      (useCase as any).logger = { log: (entry: any) => logs.push(entry), warn: () => undefined, error: () => undefined };
      await useCase.execute({ ...BASE_EVENT, webhookEventId, messageText: 'ยอดขายวันนี้เท่าไหร่' });
      const summary = logs.find((entry) => entry.msg === 'line.ai.turn_summary');
      assert.ok(summary, `${webhookEventId}: turn summary emitted`);
      return summary;
    };

    // Prepared lane: a simple_grounded plan was forwarded and the turn made no model call at all.
    const preparedTurn = await summaryFor('evt-lane-prepared', { preparedPlan: true, usage: [], semanticCoverage: [{ index: 0, status: 'handled' }] });
    assert.equal(preparedTurn.lane, 'prepared');
    assert.equal(preparedTurn.preparedPlanVersion, 1);
    assert.equal(preparedTurn.fallbackReason, null);

    // The same forwarded plan, but the gateway still composed: the plan was not used.
    const downgraded = await summaryFor('evt-lane-downgraded', { preparedPlan: true, usage: [usageEntry('line.compose')],
      semanticCoverage: [{ index: 0, status: 'handled' }] });
    assert.equal(downgraded.lane, 'semantic');
    assert.equal(downgraded.preparedPlanVersion, 1, 'a forwarded-but-unused plan stays visible next to the semantic lane');

    // Semantic lane with one item the system could not answer: its reasonCode is the fallback reason.
    const partial = await summaryFor('evt-lane-semantic', { usage: [usageEntry('line.loop'), usageEntry('line.compose')],
      semanticCoverage: [{ index: 0, status: 'handled' }, { index: 1, status: 'unsupported', reasonCode: 'TOOL_INPUT_NOT_AUTHORIZED' }] });
    assert.equal(partial.lane, 'semantic');
    assert.equal(partial.fallbackReason, 'TOOL_INPUT_NOT_AUTHORIZED');
    assert.equal(partial.costSatang, null);

    // Semantic lane answered without any model call (e.g. a period comparison): the deterministic fallback.
    const deterministic = await summaryFor('evt-lane-deterministic', { usage: [],
      semanticCoverage: [{ index: 0, status: 'handled', reasonCode: 'DETERMINISTIC_FALLBACK_RENDERED' }] });
    assert.equal(deterministic.lane, 'semantic');
    assert.equal(deterministic.fallbackReason, 'DETERMINISTIC_FALLBACK_RENDERED');
  });

  it('forwards the intake prepared plan into the turn only when a downstream lane flag is on (Phase 3/4 independent, default off)', async () => {
    const prepared = parseLineAiPreparedPlan({
      version: 1, complexity: 'simple', confidence: 0.9, responseMode: 'simple_grounded', answerShape: 'single_metric',
      intentPlan: {
        status: 'ROUTABLE', language: 'th', requiresHumanReview: false, refusals: [],
        intents: [{ intent: 'read_summary', subject: 'sale', agent: 'sales', priority: 1, requiredTools: ['sales.get_sales_summary'], missingContext: [] }],
      },
      proposedCalls: [{ toolName: 'sales.get_sales_summary', input: {} }],
    });
    assert.ok(prepared, 'prepared-plan fixture parses');
    const route = () => ({ status: 'ROUTED', intent: 'BUSINESS_READ_QUESTION', language: 'th', confidence: 0.9, preparedPlan: prepared });
    const turn = () => ({
      requestId: 'req-ai', replyText: 'ยอดขายวันนี้ 1,000 บาท', sourceRefs: [], sourceLabels: [], webLinks: [],
      intent: 'read_summary', agent: 'sales', refused: false, toolsInvoked: [], toolCalls: [],
      modelCallCount: 1, modelLineage: [], usage: [], durationMs: 10,
    });
    const silent = (useCase: unknown) => { (useCase as any).logger = { log: () => undefined, warn: () => undefined, error: () => undefined }; };

    // Default (both lane flags off): the prepared plan is NOT carried into the turn request.
    {
      const { prisma } = makePrisma();
      const { useCase, aiGatewayRequests } = makeUseCase(prisma, { permissions: ['line.ai.query'], intakeRouteFn: route, aiGatewayFn: turn });
      silent(useCase);
      await useCase.execute({ ...BASE_EVENT, webhookEventId: 'evt-fwd-off', messageText: 'ยอดขายวันนี้เท่าไหร่' });
      assert.equal(aiGatewayRequests[0]?.preparedPlan, undefined, 'default off → prepared plan not forwarded');
      // S-3: the TRUSTED outer route intent is bound on EVERY turn now — it is what lets the
      // orchestrator tell an in-system business question from an out-of-scope one (evidence E4).
      // It activates no lane on its own: the prepared simple-read lane additionally requires
      // `preparedPlan`, which the assertion above shows is still absent with the flags off.
      assert.equal(aiGatewayRequests[0]?.intakeIntent, 'BUSINESS_READ_QUESTION', 'trusted provenance is always bound');
    }

    // Phase 4 alone (prepared-simple-read on, shadow OFF): forwarded — the two lanes are independent.
    // The API binds the TRUSTED outer route intent as separate provenance (never from the wrapper).
    {
      const { prisma } = makePrisma();
      const { useCase, aiGatewayRequests } = makeUseCase(prisma, { permissions: ['line.ai.query'], config: { lineAiPreparedSimpleReadEnabled: true }, intakeRouteFn: route, aiGatewayFn: turn });
      silent(useCase);
      await useCase.execute({ ...BASE_EVENT, webhookEventId: 'evt-fwd-p4', messageText: 'ยอดขายวันนี้เท่าไหร่' });
      assert.ok(aiGatewayRequests[0]?.preparedPlan, 'prepared-simple-read on → forwarded even with shadow off');
      assert.equal(aiGatewayRequests[0].preparedPlan.version, 1);
      assert.equal(aiGatewayRequests[0].intakeIntent, 'BUSINESS_READ_QUESTION', 'trusted outer intent bound from the route');
    }

    // Phase 3 alone (shadow on, prepared-simple-read OFF): also forwarded, for the shadow comparison.
    {
      const { prisma } = makePrisma();
      const { useCase, aiGatewayRequests } = makeUseCase(prisma, { permissions: ['line.ai.query'], config: { lineAiFusedPlanShadowEnabled: true }, intakeRouteFn: route, aiGatewayFn: turn });
      silent(useCase);
      await useCase.execute({ ...BASE_EVENT, webhookEventId: 'evt-fwd-p3', messageText: 'ยอดขายวันนี้เท่าไหร่' });
      assert.ok(aiGatewayRequests[0]?.preparedPlan, 'shadow on → forwarded for comparison');
    }
  });

  /**
   * Spec §4 R-M1/R-M2, controller finding 2026-09-27: a real Bedrock run showed turn 2's intake
   * request carrying NO recentReads at all, even though turn 1 (a prepared/fast-lane list read) was
   * delivered fine. Every prior test mocks `aiGatewayFn` at the top-level RPC boundary, which skips
   * the real internal-tools-controller callback that calls `LineReadEvidenceService.record()` — so
   * nothing before this test ever ran record() → recentReadsForTurn() → deliverySources →
   * recordTurnOutcome() → loadConversationContext() end to end. This does, with no model involved:
   * turn 1 records evidence the way the real controller would, turn 2 (a FRESH use-case instance,
   * same backing store — proving this is delivery-backed memory, not process-local state, same as
   * the existing "remembers only the delivered public topic" test above) must see it in the intake
   * request it builds. The gateway's own rendering of conversationContext into the model prompt is
   * already covered by "passes bounded conversation context to model routing payloads, spec §4 R-M3
   * recentReads included" in intent-router.agent.spec.ts — this test closes the gap before it.
   */
  it('spec §4 R-M2: a delivered prepared-lane read persists memory the next turn carries into its intake request (no model)', async () => {
    const { prisma, outcomeStore } = makePrisma({
      recentTurns: [{ webhookEventId: 'evt-mem-1', createdAt: new Date(), userMessagePreview: 'ขอดูรายการล่าสุดหน่อยครับ',
        replyPreview: 'ค่าใช้จ่าย 3 รายการ', intent: 'READ_SUMMARY', agent: 'accounting', refused: false, status: 'COMPLETED' }],
    });
    // Two fixture gaps `makePrisma()` never needed before this feature: an in-memory `lineReadEvidence`
    // table (R-M1's own store) and `lineTurnOutcome.findMany` (what `loadConversationContext` reads
    // delivered evidence back through). Patched locally so the shared fixture stays untouched for
    // every other test in this file.
    const evidenceRows: any[] = [];
    prisma.client.lineReadEvidence = {
      create: async ({ data }: any) => {
        const row = { id: `evid-${evidenceRows.length + 1}`, createdAt: new Date(), ...data };
        evidenceRows.push(row);
        return { id: row.id };
      },
      count: async ({ where }: any) => evidenceRows.filter((row) =>
        row.companyId === where.companyId && row.userId === where.userId && row.requestId === where.requestId).length,
      findMany: async ({ where, take }: any) => {
        const rows = evidenceRows
          .filter((row) => row.companyId === where.companyId && row.userId === where.userId && row.requestId === where.requestId
            && (!where.toolName?.in || where.toolName.in.includes(row.toolName)))
          .sort((a, b) => a.createdAt.getTime() - b.createdAt.getTime() || a.id.localeCompare(b.id));
        return take ? rows.slice(0, take) : rows;
      },
    };
    // record()'s own transaction (advisory lock + count + create) — process-line-webhook.use-case.ts
    // never calls $transaction itself, so replacing it here cannot affect the rest of this turn.
    prisma.client.$transaction = async (work: any) => work({ $executeRaw: async () => undefined, lineReadEvidence: prisma.client.lineReadEvidence });
    prisma.client.lineTurnOutcome.findMany = async ({ where }: any) => {
      const ids: string[] = where.webhookEventId?.in ?? [];
      return ids.flatMap((id) => {
        const row = outcomeStore.get(id);
        return row && row.deliveredAt != null ? [{ webhookEventId: id, deliveredAt: row.deliveredAt, authorizationJson: row.authorizationJson }] : [];
      });
    };
    // Real service, not the harness's default `{ forTurn: async () => [] }` stub (which has no
    // recentReadsForTurn/deliveredExpenseSummaryForTurn at all) — those conditional-existence checks
    // in process-line-webhook.use-case.ts exist for that stub, so overriding with the real service is
    // what actually exercises the feature instead of always short-circuiting it to undefined. verify/
    // verifyDelivery are a SEPARATE, pre-existing re-authorization check (mayDeliverBusinessReply,
    // unrelated to R-M2) that the harness's own default stubs out the same way for every other test —
    // kept stubbed here too so this test stays about the memory chain, not that unrelated gate.
    const realReadEvidence = new LineReadEvidenceService(prisma, {} as any, new Map());
    const readEvidence = {
      record: realReadEvidence.record.bind(realReadEvidence),
      forTurn: realReadEvidence.forTurn.bind(realReadEvidence),
      deliveredExpenseSummaryForTurn: realReadEvidence.deliveredExpenseSummaryForTurn.bind(realReadEvidence),
      recentReadsForTurn: realReadEvidence.recentReadsForTurn.bind(realReadEvidence),
      verify: async () => true,
      verifyDelivery: async () => false,
    };
    const config = { lineAiPreparedSimpleReadEnabled: true, lineAiTerminalOutcomeReplayEnabled: true };
    const prepared = parseLineAiPreparedPlan({
      version: 1, complexity: 'simple', confidence: 0.9, responseMode: 'simple_grounded', answerShape: 'list',
      intentPlan: {
        status: 'ROUTABLE', language: 'th', requiresHumanReview: false, refusals: [],
        intents: [{ intent: 'read_summary', subject: 'expense', agent: 'accounting', priority: 1, requiredTools: ['expense.list_recent'], missingContext: [] }],
      },
      proposedCalls: [{ toolName: 'expense.list_recent', input: {} }],
    });
    assert.ok(prepared, 'prepared-plan fixture parses');

    // Turn 1: the prepared (fast-lane) list read the real orchestrator would serve. aiGatewayFn
    // stands in for the whole gateway turn, so it also does the ONE thing the real internal-tools
    // controller does that the mock otherwise skips: record read evidence for a successful read.
    const h1 = makeUseCase(prisma, {
      permissions: ['line.ai.query'], config,
      intakeRouteFn: () => ({ status: 'ROUTED', intent: 'BUSINESS_READ_QUESTION', language: 'th', confidence: 0.9, preparedPlan: prepared }),
      aiGatewayFn: async (req: any) => {
        await readEvidence.record({
          requestId: req.requestId, companyId: req.userContext.companyId, userId: req.userContext.internalUserId,
          membershipId: req.userContext.membershipId, permissions: req.userContext.permissions, locale: req.userContext.locale,
          chatKeyHash: req.userContext.chatKeyHash,
        }, {}, {
          toolName: 'expense.list_recent', status: 'ok',
          data: { total: 3, items: [
            { id: 'expense-1', vendorNameSnapshot: 'ร้านหนึ่ง', expenseDate: '2026-09-10T00:00:00.000Z' },
            { id: 'expense-2', vendorNameSnapshot: 'ร้านสอง', expenseDate: '2026-09-12T00:00:00.000Z' },
            { id: 'expense-3', vendorNameSnapshot: 'ร้านสามการค้า', expenseDate: '2026-09-16T00:00:00.000Z' },
          ] },
          sourceRefs: [{ module: 'expenses', entityType: 'expense', permissionChecked: true, label: 'รายการค่าใช้จ่าย' }],
          asOf: '2026-09-28T09:00:00.000Z',
        } as any);
        return {
          requestId: req.requestId, replyText: 'ค่าใช้จ่าย: 3 รายการ', sourceRefs: [], sourceLabels: [], webLinks: [],
          intent: 'read_summary', agent: 'accounting', refused: false,
          toolsInvoked: ['expense.list_recent'], toolCalls: [{ name: 'expense.list_recent', status: 'ok' }],
          modelCallCount: 1, modelLineage: [], usage: [], durationMs: 10,
        };
      },
    });
    (h1.useCase as any).readEvidence = readEvidence;
    await h1.useCase.execute({ ...BASE_EVENT, webhookEventId: 'evt-mem-1', messageText: 'ขอดูรายการล่าสุดหน่อยครับ' });

    const outcome1 = outcomeStore.get('evt-mem-1');
    assert.ok(outcome1?.deliveredAt, 'turn 1 must be recorded as delivered before its memory can carry forward');
    assert.equal(outcome1.authorizationJson?.readMemory?.entries?.[0]?.tool, 'expense.list_recent');
    assert.equal(outcome1.authorizationJson.readMemory.entries[0].shownItems[2]?.id, 'expense-3', 'R-M1 keeps display order for ordinal lookups');

    // Turn 2: a FRESH use-case instance, same backing store — same proof shape the existing "remembers
    // only the delivered public topic across instances" test above already uses for a different field.
    const h2 = makeUseCase(prisma, {
      permissions: ['line.ai.query'], config,
      intakeRouteFn: () => ({ status: 'ROUTED', intent: 'BUSINESS_READ_QUESTION', language: 'th', confidence: 0.9 }),
      aiGatewayFn: () => ({
        requestId: 'req-mem-2', replyText: 'รายการที่ 3 คือร้านสามการค้าค่ะ', sourceRefs: [], sourceLabels: [], webLinks: [],
        intent: 'read_detail', agent: 'accounting', refused: false, toolsInvoked: [], toolCalls: [],
        modelCallCount: 1, modelLineage: [], usage: [], durationMs: 10,
      }),
    });
    (h2.useCase as any).readEvidence = readEvidence;
    await h2.useCase.execute({ ...BASE_EVENT, webhookEventId: 'evt-mem-2', messageText: 'รายการที่ 3 คือร้านอะไรครับ' });

    // This is the exact drop the controller reported: the intake-route request the API builds for
    // turn 2 must itself carry recentReads with the shownItems id "รายการที่ 3" resolves to.
    assert.equal(h2.intakeRequests.length, 1);
    const recentReads = h2.intakeRequests[0]?.conversationContext?.recentReads;
    assert.ok(recentReads?.length, 'turn 2 intake request must carry turn 1 read memory');
    assert.equal(recentReads[0].tool, 'expense.list_recent');
    assert.equal(recentReads[0].shownItems?.[2]?.id, 'expense-3', '"รายการที่ 3" must resolve to the third shown item\'s id');
    assert.equal(
      recentReads[0].shownItems.some((item: any) => 'amount' in item || 'grandTotalAmount' in item),
      false,
      'R-M6: memory carries no amounts',
    );

    // Regression (present on main since v2.4 turned delivery-plan-v2 on by default, controller
    // finding 2026-09-27): sendMessagesV2's LineTurnOutcome rows carry presentationKind
    // 'delivery_plan_v2' instead of 'text'/'flex' — separately fixed in line-ledger-delivery.service.ts
    // so that write no longer nulls authorizationJson. loadConversationContext itself never switches
    // on presentationKind, so the SAME already-proven-correct row (just re-labelled, same access-proof
    // fields untouched) must keep working — and an expenseSummary proof alongside it must too, since
    // that pre-existing field shares the exact same read path and regressed the exact same way.
    outcome1.presentationKind = 'delivery_plan_v2';
    outcome1.authorizationJson = { ...outcome1.authorizationJson,
      expenseSummary: { ...outcome1.authorizationJson.readMemory, statusBasis: 'exclude_rejected_voided', continuationOfPrior: false,
        ranges: [{ fromDate: '2026-09-01', toDate: '2026-09-28', branchId: null }] } };
    delete outcome1.authorizationJson.expenseSummary.entries;
    const h3 = makeUseCase(prisma, {
      permissions: ['line.ai.query'], config,
      intakeRouteFn: () => ({ status: 'ROUTED', intent: 'BUSINESS_READ_QUESTION', language: 'th', confidence: 0.9 }),
      aiGatewayFn: () => ({
        requestId: 'req-mem-3', replyText: 'รายการที่ 3 คือร้านสามการค้าค่ะ', sourceRefs: [], sourceLabels: [], webLinks: [],
        intent: 'read_detail', agent: 'accounting', refused: false, toolsInvoked: [], toolCalls: [],
        modelCallCount: 1, modelLineage: [], usage: [], durationMs: 10,
      }),
    });
    (h3.useCase as any).readEvidence = readEvidence;
    await h3.useCase.execute({ ...BASE_EVENT, webhookEventId: 'evt-mem-3', messageText: 'รายการที่ 3 คือร้านอะไรครับ' });
    const recentReadsV2 = h3.intakeRequests[0]?.conversationContext?.recentReads;
    assert.ok(recentReadsV2?.length, 'a delivery_plan_v2-labelled outcome must still surface recentReads');
    assert.equal(recentReadsV2[0].shownItems?.[2]?.id, 'expense-3');
    assert.ok(h3.intakeRequests[0]?.conversationContext?.deliveredExpenseSummary, 'and deliveredExpenseSummary, which regressed the same way on the v2 path');
  });

  /**
   * Spec `line-ai-draft-control-spec-th.md` §5.3, case E4, replayed end to end from the UAT log of
   * 2026-09-03. The owner asked why the service charge on his own bill was a separate line. The
   * intake router placed it BUSINESS_READ_QUESTION at 0.55 — too low to propose a tool, so it
   * emitted NO prepared plan — and the API only bound `intakeIntent` inside the prepared-plan
   * block. The gateway therefore never learned the turn was business, and the owner was told his
   * own expense record was outside the system.
   */
  it('carries the trusted intake provenance for a business turn the router had no plan for (E4)', async () => {
    const { prisma } = makePrisma();
    const { useCase, replies, aiGatewayRequests } = makeUseCase(prisma, {
      permissions: ['line.ai.query'],
      // Exactly the shape the router emits for E4: routed, business, low confidence, NO preparedPlan.
      intakeRouteFn: () => ({ status: 'ROUTED', intent: 'BUSINESS_READ_QUESTION', language: 'th', confidence: 0.55 }),
      // The gateway answers with the copy it composes once it sees the provenance.
      aiGatewayFn: (request: any) => {
        const business = request.intakeIntent === 'BUSINESS_READ_QUESTION';
        return {
          requestId: 'req-e4',
          replyText: business
            ? '📋 เรื่องนี้อยู่ในระบบ แต่น้องมั่งมียังทำผ่าน LINE ไม่ได้ในตอนนี้ค่ะ\nทำได้ในเว็บนะคะ'
            : '📋 ขออภัยค่ะ น้องมั่งมีตอบได้เฉพาะข้อมูลในระบบธุรกิจที่เชื่อมต่ออยู่เท่านั้น\nคำถามนี้อยู่นอกขอบเขตระบบ จึงไม่สามารถให้ข้อมูลที่น่าเชื่อถือได้ค่ะ',
          sourceRefs: [], sourceLabels: [], webLinks: [],
          intent: 'unsupported_module', agent: 'general',
          refused: true, refusalReason: business ? 'unsupported_yet' : 'unsupported_module',
          toolsInvoked: [], toolCalls: [], modelCallCount: 1, modelLineage: [], usage: [], durationMs: 10,
        };
      },
    });
    (useCase as any).logger = { log: () => undefined, warn: () => undefined, error: () => undefined };

    await useCase.execute({
      ...BASE_EVENT, webhookEventId: 'evt-e4',
      messageText: 'ทำไม service charge คิดแยกเป็นอีกรายการ',
    });

    assert.equal(aiGatewayRequests[0]?.preparedPlan, undefined, 'the router had no confident tool, so no plan');
    assert.equal(aiGatewayRequests[0]?.intakeIntent, 'BUSINESS_READ_QUESTION', 'and the provenance still reaches the gateway');
    assert.match(replies.join('\n'), /เรื่องนี้อยู่ในระบบ แต่น้องมั่งมียังทำผ่าน LINE ไม่ได้/);
    assert.equal(replies.join('\n').includes('นอกขอบเขตระบบ'), false, 'his own expense record is not out of scope');
  });

