  // A4: the SIGNATURE_UPLOAD_TICKET route depends on an AI call that can come back UNAVAILABLE or
  // low-confidence. Every degraded turn used to send a signature photo down expense capture instead.
  it('creates the signature asset from an explicit caption even when the intake router is unavailable', async () => {
    const { prisma } = makePrisma();
    const created: any[] = [];
    const delivered: string[] = [];
    let receiptIntents = 0;
    const { useCase } = makeUseCase(prisma, {
      permissions: ['expense.receipt.line_upload', 'expense.receipt.upload', 'attachment.create', 'expense.signature.manage'],
      intakeRouteFn: () => ({ status: 'UNAVAILABLE' }),
      // The ticket reply is delivered as several bubbles; the link is not in the first one.
      sendReplyFn: async (_token: string, messages: any[]) => { delivered.push(JSON.stringify(messages)); return 'ok'; },
      initReceiptUpload: { execute: async () => { receiptIntents += 1; return { expenseId: 'exp-1', attachmentId: 'att-1' }; } },
      completeReceiptUpload: { execute: async () => undefined },
      initSignatureUpload: { execute: async () => ({ attachmentId: 'att-sig', uploadUrl: 'https://upload', uploadMethod: 'PUT', uploadHeaders: {} }) },
      createSignatureAsset: { execute: async (_ctx: any, cmd: any) => { created.push(cmd); return { id: 'sig-9', status: 'ACTIVE' }; } },
    });
    (useCase as any).downloadLineMedia = async () => ({ ok: true, media: ({
      fileName: 'signature.jpg', mimeType: 'image/jpeg', byteSize: JPEG_BYTES.byteLength,
      checksumSha256: 'hash', contentBase64: JPEG_BYTES.toString('base64'), bytes: JPEG_BYTES,
    }) });
    (useCase as any).uploadLineMedia = async () => undefined;

    await useCase.executeReceiptUpload({
      webhookEventId: 'evt-sig-caption',
      lineUserId: 'line-user-secret',
      replyToken: 'reply-sig-caption',
      lineMessageId: 'line-msg-sig',
      messageType: 'image',
      messagingChannelId: 'msg-channel-1',
    }, 'ลายเซ็นของผมครับ');

    assert.equal(created.length, 1);
    assert.equal(created[0].submittedFromChannel, 'LINE');
    assert.equal(created[0].lineMessageId, 'line-msg-sig');
    assert.equal(receiptIntents, 0, 'a signature must never be captured as an expense');
    // A2: the ticket link points at the un-parked screen, not the parked ?tab= query.
    assert.match(delivered.join('\n'), /expenses\/signatures\?signatureId=sig-9/);
  });

  // F8: the “ตอบ 1” steer used to fire only on the numbered pending-media route. A captioned photo
  // took the deterministic route and stranded a sender who was mid-issue-decision with no steer.
  it('rechecks the original LINE identity after signature storage on both routed and caption paths', async () => {
    for (const routed of [false, true]) {
      const { prisma } = makePrisma();
      let checked = 0, activated = 0;
      const { useCase, replies } = makeUseCase(prisma, {
        permissions: ['expense.receipt.line_upload', 'expense.receipt.upload', 'attachment.create', 'expense.signature.manage'],
        intakeRouteFn: () => routed
          ? { status: 'ROUTED', intent: 'SIGNATURE_UPLOAD_TICKET', language: 'th', confidence: 0.99 }
          : { status: 'UNAVAILABLE' },
        initReceiptUpload: { execute: async () => { throw new Error('signature must not create an expense'); } },
        completeReceiptUpload: { execute: async () => undefined },
        initSignatureUpload: { execute: async () => ({ attachmentId: 'att-sig', uploadUrl: 'https://upload', uploadMethod: 'PUT', uploadHeaders: {} }) },
        createSignatureAsset: { execute: async (_ctx: any, _cmd: any, source: any) => {
          (useCase as any).resolveLineIdentity = async () => null;
          assert.equal(typeof source?.beforeCommit, 'function');
          checked += 1; await source.beforeCommit(); activated += 1;
          return { id: 'sig-denied', status: 'ACTIVE' };
        } },
      });
      (useCase as any).downloadLineMedia = async () => ({ ok: true, media: ({
        fileName: 'signature.jpg', mimeType: 'image/jpeg', byteSize: JPEG_BYTES.byteLength,
        contentBase64: JPEG_BYTES.toString('base64'), bytes: JPEG_BYTES,
      }) });
      (useCase as any).uploadLineMedia = async () => undefined;
      await useCase.executeReceiptUpload({
        webhookEventId: `sig-storage-${routed}`, lineUserId: 'line-user-secret', replyToken: 'sig-reply',
        lineMessageId: `sig-message-${routed}`, messageType: 'image', messagingChannelId: 'msg-channel-1',
      }, 'ลายเซ็นของผมครับ');
      assert.equal(checked, 1); assert.equal(activated, 0);
      assert.doesNotMatch(replies.join('\n'), /sig-denied|ใช้ลงนามเอกสารได้ทันที/);
    }
  });

  it('steers the caption-route signature to preparation only when the issue decision is pending (F8)', async () => {
    const runCaption = async (pendingIssueDecision: boolean) => {
      const { prisma } = makePrisma();
      const delivered: string[] = [];
      const { useCase } = makeUseCase(prisma, {
        permissions: ['expense.receipt.line_upload', 'expense.receipt.upload', 'attachment.create', 'expense.signature.manage'],
        intakeRouteFn: () => ({ status: 'UNAVAILABLE' }),
        sendReplyFn: async (_t: string, messages: any[]) => { delivered.push(JSON.stringify(messages)); return 'ok'; },
        initReceiptUpload: { execute: async () => ({ expenseId: 'exp-1', attachmentId: 'att-1' }) },
        completeReceiptUpload: { execute: async () => undefined },
        initSignatureUpload: { execute: async () => ({ attachmentId: 'att-sig', uploadUrl: 'https://upload', uploadMethod: 'PUT', uploadHeaders: {} }) },
        createSignatureAsset: { execute: async () => ({ id: 'sig-9', status: 'ACTIVE' }) },
        substituteReceiptContinuation: { hasPendingIssueDecision: async () => pendingIssueDecision },
      });
      (useCase as any).downloadLineMedia = async () => ({ ok: true, media: ({
        fileName: 'signature.jpg', mimeType: 'image/jpeg', byteSize: JPEG_BYTES.byteLength,
        checksumSha256: 'hash', contentBase64: JPEG_BYTES.toString('base64'), bytes: JPEG_BYTES,
      }) });
      (useCase as any).uploadLineMedia = async () => undefined;
      await useCase.executeReceiptUpload({
        webhookEventId: `evt-sig-${pendingIssueDecision}`, lineUserId: 'line-user-secret',
        replyToken: 'reply-sig', lineMessageId: 'line-msg-sig', messageType: 'image', messagingChannelId: 'msg-channel-1',
      }, 'ลายเซ็นของผมครับ');
      return delivered.join('\n');
    };

    assert.match(await runCaption(true), /กดเตรียมใบรับรอง/, 'steers when a decision is pending');
    assert.doesNotMatch(await runCaption(false), /กดเตรียมใบรับรอง/, 'no steer when nothing is pending');
  });

  // F1: `ลายเซ็น` is a substring test, and plenty of real receipts mention it ("ค่าทำป้ายลายเซ็น").
  // Reading that as intent filed the receipt as the newest reusable signature for legal documents —
  // ACTIVE and signable on the spot — and lost the expense entirely. A router that saw both the
  // caption and the picture outranks a regex; the deterministic route is for when it said nothing.
  it('leaves a ROUTED expense capture alone even when its caption mentions ลายเซ็น', async () => {
    const { prisma } = makePrisma();
    const signatureCreated: any[] = [];
    let receiptIntents = 0;
    const { useCase } = makeUseCase(prisma, {
      permissions: ['expense.receipt.line_upload', 'expense.receipt.upload', 'attachment.create', 'expense.signature.manage', 'expense.create'],
      intakeRouteFn: () => ROUTED_EXPENSE_DOCUMENT,
      receiptOcrFn: () => ({ status: 'ok', classification: receiptClassification('500.00'), fields: { grandTotalAmount: '500.00' } }),
      initReceiptUpload: { execute: async () => { receiptIntents += 1; return { expenseId: 'exp-1', attachmentId: 'att-1' }; } },
      completeReceiptUpload: { execute: async () => ({ id: 'exp-1', duplicateStatus: 'NONE' }) },
      initSignatureUpload: { execute: async () => ({ attachmentId: 'att-sig', uploadUrl: 'https://upload', uploadMethod: 'PUT', uploadHeaders: {} }) },
      createSignatureAsset: { execute: async (_ctx: any, cmd: any) => { signatureCreated.push(cmd); return { id: 'sig-9', status: 'ACTIVE' }; } },
    });
    (useCase as any).downloadLineMedia = async () => ({ ok: true, media: ({
      fileName: 'receipt.jpg', mimeType: 'image/jpeg', byteSize: JPEG_BYTES.byteLength,
      checksumSha256: 'hash', contentBase64: JPEG_BYTES.toString('base64'), bytes: JPEG_BYTES,
    }) });
    (useCase as any).uploadLineMedia = async () => undefined;

    await useCase.executeReceiptUpload({
      webhookEventId: 'evt-sig-incidental',
      lineUserId: 'line-user-secret',
      replyToken: 'reply-sig-incidental',
      lineMessageId: 'line-msg-incidental',
      messageType: 'image',
      messagingChannelId: 'msg-channel-1',
    }, 'ค่าทำป้ายลายเซ็น 500 บาท');

    assert.deepEqual(signatureCreated, [], 'a routed receipt must never become a signature asset');
    assert.equal(receiptIntents, 1, 'the expense capture the router asked for must still happen');
  });

  it('uses a gateway-validated one-pass receipt without calling or reserving the receipt OCR step (a captioned photo keeps the router)', async () => {
    const { prisma } = makePrisma();
    let receiptOcrCalls = 0;
    let receiptIntents = 0;
    const classification = receiptClassification('65.00');
    const { useCase, auditEvents } = makeUseCase(prisma, {
      permissions: ['expense.receipt.line_upload', 'expense.receipt.upload', 'attachment.create', 'expense.create'],
      intakeRouteFn: () => ({
        ...ROUTED_EXPENSE_DOCUMENT,
        ocrAdmission: 'admitted',
        onePassReceipt: {
          classification,
          fields: { vendorName: 'ร้านกาแฟ', expenseDate: '2026-09-21', description: 'ลาเต้', grandTotalAmount: '65.00', confidence: 0.96 },
        },
      }),
      receiptOcrFn: () => { receiptOcrCalls += 1; throw new Error('one-pass must short-circuit before receipt OCR'); },
      initReceiptUpload: { execute: async () => { receiptIntents += 1; return { expenseId: 'exp-one-pass', attachmentId: 'att-one-pass' }; } },
      completeReceiptUpload: { execute: async () => ({ id: 'exp-one-pass', duplicateStatus: 'NONE' }) },
    });
    (useCase as any).downloadLineMedia = async () => ({ ok: true, media: ({
      fileName: 'receipt.jpg', mimeType: 'image/jpeg', byteSize: JPEG_BYTES.byteLength,
      checksumSha256: 'hash', contentBase64: JPEG_BYTES.toString('base64'), bytes: JPEG_BYTES,
    }) });
    (useCase as any).uploadLineMedia = async () => undefined;

    await useCase.executeReceiptUpload({
      webhookEventId: 'evt-one-pass', lineUserId: 'line-user-secret', replyToken: 'reply-one-pass',
      lineMessageId: 'line-msg-one-pass', messageType: 'image', messagingChannelId: 'msg-channel-1',
    }, 'ค่ากาแฟ');

    assert.equal(receiptOcrCalls, 0, 'no second gateway step means no second money reservation or provider call');
    assert.equal(receiptIntents, 1, 'the validated fields still enter the existing reviewed receipt workflow');
    const ocrAudit = auditEvents.find((row: any) => row.action === 'expense.ocr.request');
    assert.equal(ocrAudit?.metadataJson?.processingPath, 'one_pass');
  });

  it('captures every row through full-read fallback at 31 and 200 rows for paid and free source drafts', async () => {
    for (const free of [false, true]) for (const count of [31, 200]) {
      const { prisma } = makePrisma();
      const saved = savedMediaFixture(`fallback-${free}-${count}`);
      const lines = Array.from({ length: count }, (_, index) => ({ description: `สินค้า ${index + 1}`, quantity: '1', amount: '10.00' }));
      const total = `${count * 10}.00`;
      const documentText = ['ใบเสร็จ', 'ร้านกาแฟ', ...lines.map(line => `${line.description} 10.00`), `รวม ${total}`, 'ชำระแล้ว'].join('\n');
      let reads = 0, applies = 0;
      const { useCase, auditEvents } = makeUseCase(prisma, {
        freeExpenseDrafts: free,
        permissions: ['expense.receipt.line_upload', 'expense.receipt.upload', 'attachment.create', ...(free ? [] : ['expense.create'])],
        intakeRouteFn: () => ({ ...ROUTED_EXPENSE_DOCUMENT, documentText, ocrAdmission: 'admitted' }),
        receiptOcrFn: (request, options) => {
          reads += 1;
          assert.equal(request.documentText, free ? undefined : documentText, 'paid fallback forwards the entire read; free source drafts read directly');
          assert.equal(options.ocrAlreadyAdmitted, !free);
          return { status: 'ok', classification: receiptClassification(total), fields: {
            vendorName: 'ร้านกาแฟ', expenseDate: '2026-09-21', grandTotalAmount: total, lines,
          } };
        },
        initReceiptUpload: { execute: async () => ({ expenseId: saved.id, attachmentId: 'att-fallback' }) },
        completeReceiptUpload: { execute: async () => ({ ...saved, duplicateStatus: 'NONE' }) },
        receiptOcrApply: { apply: async (_ctx: any, id: string, fields: any, options: any) => {
          applies += 1;
          assert.equal(id, saved.id);
          assert.equal(Boolean(options.sourceOnly), free);
          assert.deepEqual(fields.lines, lines);
          saved.lines = structuredClone(fields.lines);
          saved.grandTotalAmount = fields.grandTotalAmount;
          saved.updatedAt = new Date(saved.updatedAt.getTime() + 1);
          return { committedUpdatedAt: saved.updatedAt, candidatesCreated: 0, dateVerified: true, dateStatus: 'verified', charges: [] };
        } },
        expenseRepo: {
          listCategories: async () => [], findById: async () => structuredClone(saved),
          findByLineMessageId: async () => null,
          findByIdWithRelations: async () => structuredClone(saved),
          updateExpense: async ({ id, companyId, expectedUpdatedAt, ...data }: any) =>
            updateSavedMedia(saved, { where: { id, companyId, updatedAt: expectedUpdatedAt }, data }),
        },
      });
      prisma.client.expenseRecord.update = async (args: any) => updateSavedMedia(saved, args);
      (useCase as any).downloadLineMedia = async () => ({ ok: true, media: {
        fileName: 'receipt.jpg', mimeType: 'image/jpeg', byteSize: JPEG_BYTES.byteLength,
        checksumSha256: 'hash', contentBase64: JPEG_BYTES.toString('base64'), bytes: JPEG_BYTES,
      } });
      (useCase as any).uploadLineMedia = async () => undefined;
      await useCase.executeReceiptUpload({ webhookEventId: `evt-${saved.id}`, lineUserId: 'line-user-secret',
        replyToken: 'reply-fallback', lineMessageId: `message-${saved.id}`, messageType: 'image', messagingChannelId: 'msg-channel-1' }, 'บันทึกบิลนี้');
      assert.equal(reads, 1);
      assert.equal(applies, 1);
      assert.deepEqual(saved.lines, lines);
      assert.equal(auditEvents.find((row: any) => row.action === 'expense.ocr.request')?.metadataJson?.processingPath, 'receipt_ocr');
    }
  });

  // P10-L §15.1 / review G-01. The ceiling itself lives in `admitCompanyOcr` (one seam, one number);
  // the LINE lane's whole job is to ANSWER its refusal — the shop needs a bigger package, and the
  // generic "อ่านรูปนี้ไม่สำเร็จ" clarify would send it looking for a better photo instead.
  describe('receipt quota answer', () => {
    const FREE_TRIAL = { tierKey: 'FREE_TRIAL_15', monthlySlipLimit: 15 } as const;
    /** What `AiGatewayClient` returns once `admitCompanyOcr` refuses on the plan ceiling. */
    const QUOTA_DENIED_ROUTE = {
      status: 'UNAVAILABLE', intent: 'UNSUPPORTED', language: 'th', confidence: 0,
      errorCode: 'ROUTER_UNREACHABLE', ocrAdmission: 'denied', ocrErrorCode: 'RECEIPT_QUOTA_EXCEEDED',
    } as const;
    /** The same refusal where a caption-less photo is admitted — at the reader (UAT 2026-09-29). */
    const QUOTA_DENIED_READ = { status: 'failed', errorCode: 'RECEIPT_QUOTA_EXCEEDED' } as const;

    const captureUseCase = (prisma: any, over: Record<string, unknown> = {}) => {
      const made = makeUseCase(prisma, {
        // A reader who may buy (advisor spec §2.2), so the §7 card keeps its buttons; see the member test below.
        permissions: ['expense.receipt.line_upload', 'expense.receipt.upload', 'attachment.create', 'expense.create', 'company.plan.manage'],
        intakeRouteFn: () => ROUTED_EXPENSE_DOCUMENT,
        receiptOcrFn: () => ({ status: 'ok', classification: receiptClassification('500.00'), fields: { grandTotalAmount: '500.00' } }),
        initReceiptUpload: { execute: async () => ({ expenseId: 'exp-1', attachmentId: 'att-1' }) },
        completeReceiptUpload: { execute: async () => ({ id: 'exp-1', duplicateStatus: 'NONE' }) },
        ...over,
      });
      (made.useCase as any).downloadLineMedia = async () => ({ ok: true, media: ({
        fileName: 'receipt.jpg', mimeType: 'image/jpeg', byteSize: JPEG_BYTES.byteLength,
        checksumSha256: 'hash', contentBase64: JPEG_BYTES.toString('base64'), bytes: JPEG_BYTES,
      }) });
      (made.useCase as any).uploadLineMedia = async () => undefined;
      return made;
    };
    const sendReceipt = (useCase: any, id: string, caption?: string) => useCase.executeReceiptUpload({
      webhookEventId: `evt-${id}`, lineUserId: 'line-user-secret', replyToken: `reply-${id}`,
      lineMessageId: `line-msg-${id}`, messageType: 'image', messagingChannelId: 'msg-channel-1',
    }, caption);

    // A caption-less photo is admitted by the reader; a captioned one still by the router. Same card.
    for (const lane of ['reader', 'router'] as const) it(`answers the refused receipt with the §7 card, and never reads or captures it (${lane} admission)`, async () => {
      const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 15 });
      let ocrCalls = 0;
      let intents = 0;
      const { useCase, sentMessages } = captureUseCase(state.prisma, {
        intakeRouteFn: () => QUOTA_DENIED_ROUTE,
        receiptOcrFn: () => {
          ocrCalls += 1;
          return lane === 'reader' ? QUOTA_DENIED_READ : { status: 'ok', classification: receiptClassification('1.00'), fields: {} };
        },
        initReceiptUpload: { execute: async () => { intents += 1; return { expenseId: 'exp-1', attachmentId: 'att-1' }; } },
      });

      await sendReceipt(useCase, 'quota-16', lane === 'router' ? 'บันทึกค่าใช้จ่าย' : undefined);

      assert.equal(ocrCalls, lane === 'reader' ? 1 : 0, 'one admission, refused: nothing is read after it');
      assert.equal(intents, 0, 'and no expense record for a receipt nobody read');
      const card = sentMessages[0];
      assert.equal(card.type, 'flex');
      assert.match(card.altText, /ช่วงทดลองให้ AI อ่านรูปได้ 15 ครั้ง ตอนนี้ครบแล้วค่ะ/);
      assert.match(card.altText, /ใบเสร็จ 1 ใบ = 1 ครั้ง/, 'the promise says what a receipt actually costs');
      assert.deepEqual(
        flexButtons(card).map((button: any) => button.action.label),
        ['ดูแพ็กเกจ', 'ขอเปลี่ยนแพ็กเกจ'],
      );
    });

    it('does not fall through to the generic "อ่านรูปนี้ไม่สำเร็จ" clarify', async () => {
      const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 15 });
      const { useCase, replies } = captureUseCase(state.prisma, { receiptOcrFn: () => QUOTA_DENIED_READ });

      await sendReceipt(useCase, 'quota-clarify');

      assert.doesNotMatch(replies.join('\n'), /อ่านรูปนี้ไม่สำเร็จ|รูปนี้เป็นอะไรคะ/);
    });

    it('sends the card ONCE per month; the next over-quota receipt gets one line (spec §3.7)', async () => {
      const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 15 });
      const { useCase, sentMessages } = captureUseCase(state.prisma, { receiptOcrFn: () => QUOTA_DENIED_READ });

      await sendReceipt(useCase, 'quota-a');
      await sendReceipt(useCase, 'quota-b');

      assert.equal(state.quotaNoticeSentMonthKey(), bangkokMonthKey());
      assert.equal(sentMessages[0].type, 'flex', 'the first wall hit is the card');
      assert.equal(sentMessages[1].type, 'flex');
      assert.ok(isLineSystemCard(sentMessages[1]));
      assert.match(sentMessages[1].canonicalText, /ขอเปลี่ยนแพ็กเกจ/);
    });

    // Advisor spec §2.2 (Owner 2026-09-30): a member without `company.plan.manage` meets the same wall
    // but is offered no package action — neither on the card nor in the follow-up line.
    it('gives a member who may not buy the card without buttons, and a follow-up that names who to ask', async () => {
      const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 15 });
      const { useCase, sentMessages } = captureUseCase(state.prisma, {
        permissions: ['expense.receipt.line_upload', 'expense.receipt.upload', 'attachment.create', 'expense.create'],
        receiptOcrFn: () => QUOTA_DENIED_READ,
      });

      await sendReceipt(useCase, 'member-a');
      await sendReceipt(useCase, 'member-b');

      assert.equal(sentMessages[0].type, 'flex');
      assert.equal(sentMessages[0].contents.footer, undefined, 'no package button for a member');
      assert.match(sentMessages[0].altText, /ช่วงทดลองให้ AI อ่านรูปได้ 15 ครั้ง ตอนนี้ครบแล้วค่ะ/);
      assert.match(sentMessages[0].altText, /แจ้งเจ้าของกิจการหรือผู้มีสิทธิ์จัดการแพ็กเกจ/);
      assert.equal(sentMessages[1].type, 'flex');
      assert.ok(isLineSystemCard(sentMessages[1]));
      assert.match(sentMessages[1].canonicalText, /แจ้งเจ้าของกิจการหรือผู้มีสิทธิ์จัดการแพ็กเกจ/);
      assert.doesNotMatch(JSON.stringify(sentMessages), /ดูแพ็กเกจ|ขอเปลี่ยนแพ็กเกจ|โปรโมชั่น/);
    });

    // Owner 2026-09-30 ("ทุกกรณีที่ระบบรับไว้ก่อน"): a photo accepted before the credit ran out is replayed by
    // the orphan sweep; its intake and its read may pass the AI money cap. A fresh photo asks neither.
    it('lets an orphan-replayed photo pass the money cap on its intake and its read, and a fresh one not', async () => {
      for (const replay of [true, false]) {
        const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 0 });
        const intake: any[] = [];
        const reads: any[] = [];
        const { useCase } = captureUseCase(state.prisma, {
          intakeRouteFn: (_req: any, options: any) => { intake.push(options); return ROUTED_EXPENSE_DOCUMENT; },
          receiptOcrFn: (_req: any, options: any) => {
            reads.push(options);
            return { status: 'ok', classification: receiptClassification('500.00'), fields: { grandTotalAmount: '500.00' } };
          },
        });

        await useCase.executeReceiptUpload({
          webhookEventId: `evt-photo-${replay}`, lineUserId: 'line-user-secret', replyToken: `reply-photo-${replay}`,
          lineMessageId: `line-msg-photo-${replay}`, messageType: 'image', messagingChannelId: 'msg-channel-1',
          ...(replay ? { admitOverCap: true as const } : {}),
        }, 'บันทึกค่าใช้จ่าย');

        assert.equal(intake[0]?.admitOverCap, replay ? true : undefined, `intake, replay=${replay}`);
        assert.equal(reads[0]?.admitOverCap, replay ? true : undefined, `read, replay=${replay}`);
      }
    });

    // Add-on plan PR B / AO-E70 (spec §6, F-19): the claim is per month AND balance generation. Units
    // bought or given mid-month start a generation, so running out again earns the card with its buttons
    // again — and adding them wrote nothing to CompanyPlanTerm for this to notice.
    it('sends the card again after new add-on units start a new generation in the same month', async () => {
      const state = makePrisma({ planTerm: { tierKey: 'STARTER_249', monthlySlipLimit: 30 }, receiptsUsed: 30 });
      const { useCase, sentMessages } = captureUseCase(state.prisma, { receiptOcrFn: () => QUOTA_DENIED_READ });

      await sendReceipt(useCase, 'gen-a');
      await sendReceipt(useCase, 'gen-b');
      assert.deepEqual(sentMessages.map((message: any) => message.type), ['flex', 'flex'], 'the follow-up uses the locked notice card');
      assert.equal(state.quotaNoticeSentMonthKey(), bangkokMonthKey(), 'no add-on lot: the bare month key, as before');

      const lotAt = new Date('2026-09-29T05:00:00.000Z');
      state.addOnLotCreated(lotAt);
      await sendReceipt(useCase, 'gen-c');
      await sendReceipt(useCase, 'gen-d');
      assert.deepEqual(sentMessages.map((message: any) => message.type), ['flex', 'flex', 'flex', 'flex'], 'each generation keeps its package card and locked follow-up');
      assert.equal(state.quotaNoticeSentMonthKey(), `${bangkokMonthKey()}#${lotAt.getTime()}`);
    });

    it('names the full trial allowance despite a legacy warmup-ten window', async () => {
      const state = makePrisma({
        planTerm: { ...FREE_TRIAL, warmupUntil: new Date(Date.now() + 86_400_000), warmupSlipLimit: 10 },
        receiptsUsed: 15,
      });
      const { useCase, sentMessages } = captureUseCase(state.prisma, { receiptOcrFn: () => QUOTA_DENIED_READ });

      await sendReceipt(useCase, 'warmup-16');

      assert.match(sentMessages[0].altText, /15 ครั้ง/);
      assert.doesNotMatch(sentMessages[0].altText, /10 ครั้ง/);
    });

    it('never tells a PAYING tier it is on a trial', async () => {
      const state = makePrisma({ planTerm: { tierKey: 'STARTER_249', monthlySlipLimit: 30 }, receiptsUsed: 30 });
      const { useCase, sentMessages } = captureUseCase(state.prisma, { receiptOcrFn: () => QUOTA_DENIED_READ });

      await sendReceipt(useCase, 'starter-31');

      assert.doesNotMatch(sentMessages[0].altText, /ทดลอง/, 'a STARTER shop bought this, it is not trialling');
      assert.match(sentMessages[0].altText, /แพ็กเกจของคุณให้ AI อ่านรูปได้ 30 ครั้งต่อเดือน/);
    });

    // F5: the month is claimed BEFORE the send so the card is exactly-once. A failed send would
    // otherwise spend the shop's only card of the month on a message nobody received.
    it('gives the month back when the card cannot be delivered', async () => {
      const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 15 });
      const delivered: any[] = [];
      let turn = 0;
      // Reply token expired AND the push fallback is throttled — the only shape where the card
      // truly never lands, since a failed reply alone still reaches the shop by push.
      const { useCase } = captureUseCase(state.prisma, {
        receiptOcrFn: () => QUOTA_DENIED_READ,
        sendReplyFn: async (_token: string, messages: any[]) => {
          if (turn === 0) return 'failed_token';
          delivered.push(messages[0]);
          return 'ok';
        },
        sendPushFn: async () => 'failed_other',
      });

      await sendReceipt(useCase, 'undelivered');
      assert.equal(state.quotaNoticeSentMonthKey(), null, 'a card nobody received does not spend the month');

      // The next image this month therefore still gets the full card, not the terse follow-up.
      turn = 1;
      await sendReceipt(useCase, 'retry');
      assert.equal(state.quotaNoticeSentMonthKey(), bangkokMonthKey());
      assert.equal(delivered[0].type, 'flex');
      assert.match(delivered[0].altText, /ช่วงทดลองให้ AI อ่านรูปได้ 15 ครั้ง/);
    });

    it('keeps the automatic receipt summary free of quota counters across tiers', async () => {
      for (const tierKey of ['FREE_TRIAL_15', 'STARTER_249'] as const) {
        const state = makePrisma({ planTerm: { tierKey, monthlySlipLimit: 15 }, receiptsUsed: 3 });
        const { useCase, replies } = captureUseCase(state.prisma);

        await sendReceipt(useCase, `counter-${tierKey}`);

        assert.doesNotMatch(replies.join('\n'), /อ่านครั้งที่/, tierKey);
      }
    });

    it('does not query presentation quota after an admitted receipt crosses the month boundary', async () => {
      const admissionMonth = '2026-08';
      assert.notEqual(admissionMonth, bangkokMonthKey(), 'the fixture must not be the current month');
      const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 15 });
      const monthsRead: Array<string | undefined> = [];
      (state.prisma.client as any).companyOcrUsageEvent = {
        count: async ({ where }: any) => {
          monthsRead.push(where.monthKey);
          assert.deepEqual(where.sourceRoute.in, ['receipt-ocr-web', 'receipt-ocr-line']);
          return 15;
        },
      };
      const { useCase, replies } = captureUseCase(state.prisma, {
        intakeRouteFn: () => ({ ...ROUTED_EXPENSE_DOCUMENT, ocrAdmission: 'admitted', ocrMonthKey: admissionMonth }),
      });

      await sendReceipt(useCase, 'month-boundary');

      assert.deepEqual(monthsRead, [], 'successful summary needs no extra quota read');
      assert.doesNotMatch(replies.join('\n'), /อ่านครั้งที่/);
    });

    it('still admits fallback OCR once without reading a presentation counter', async () => {
      const admissionMonth = '2026-08';
      assert.notEqual(admissionMonth, bangkokMonthKey(), 'the reply is built after the admitted month');
      const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 15 });
      const monthsRead: string[] = [];
      state.prisma.client.companyOcrUsageEvent.count = async ({ where }: any) => {
        monthsRead.push(where.monthKey);
        return where.monthKey === admissionMonth ? 15 : 0;
      };
      let receiptAdmissions = 0;
      const { useCase, replies } = captureUseCase(state.prisma, {
        intakeRouteFn: () => ({ status: 'UNAVAILABLE', intent: 'UNSUPPORTED', language: 'th', confidence: 0,
          errorCode: 'PROVIDER_DISABLED', ocrAdmission: 'denied' }),
        receiptOcrFn: (_request: any, options: any) => {
          assert.equal(options.ocrAlreadyAdmitted, false);
          receiptAdmissions += 1;
          options.onAdmitted({ eventId: 'fallback-admission', monthKey: admissionMonth });
          return { status: 'ok', classification: receiptClassification('500.00'), fields: { grandTotalAmount: '500.00' } };
        },
      });

      await sendReceipt(useCase, 'fallback-month-boundary');

      assert.equal(receiptAdmissions, 1);
      assert.deepEqual(monthsRead, [], 'the receipt summary does not read a quota counter');
      assert.doesNotMatch(replies.join(' '), /อ่านครั้งที่/);
    });

    it('does not announce a successful read counter for an uploaded source whose OCR application failed', async () => {
      const state = makePrisma({ planTerm: FREE_TRIAL, receiptsUsed: 3 });
      let storedImages = 0;
      const { useCase, replies } = captureUseCase(state.prisma, {
        completeReceiptUpload: { execute: async () => { storedImages += 1; return { id: 'exp-1', duplicateStatus: 'NONE' }; } },
        receiptOcrApply: { apply: async () => ({ candidatesCreated: 0, staleSkipped: true }) },
      });
      await sendReceipt(useCase, 'partial-no-counter');
      assert.equal(storedImages, 1);
      assert.doesNotMatch(replies.join(' '), /อ่านครั้งที่/);
    });

    it('says nothing about a counter for a legacy shop with no plan term', async () => {
      const state = makePrisma({ receiptsUsed: 3 });
      const { useCase, replies } = captureUseCase(state.prisma);

      await sendReceipt(useCase, 'legacy');

      assert.doesNotMatch(replies.join('\n'), /ในช่วงทดลอง/);
    });
  });

  // A3 answer half + F9. Certification resolves signatures through a PNG/JPEG-only lookup, so a PDF
  // answered as "my signature" would become an ACTIVE asset that can never sign anything — a dead
  // end from the first turn, since nothing is held for review any more.
  it('turns the numbered signature answer into a usable asset that steers back to the decision, and refuses a PDF outright', async () => {
    const answerEvent = {
      webhookEventId: 'evt-sig-answer', lineUserId: 'line-user-secret', replyToken: 'reply-sig-answer',
      messageText: '1', messagingChannelId: 'msg-channel-1',
    } as any;
    const chatKeyHash = chatKeyHashOf(answerEvent);
    const asked = { kind: 'SUBSTITUTE_MEDIA_CLASS', chatKeyHash, choices: ['SIGNATURE', 'PAYMENT_EVIDENCE', 'SUPPORTING_EVIDENCE', 'NEW_EXPENSE', 'NO_RECORD'] };
    const access = { membershipId: 'mem-1', roles: ['STAFF'], permissions: [], scopes: {} } as any;

    const run = async (mimeType: string) => {
      const { prisma } = makePrisma();
      (prisma.client as any).lineIntakePendingMedia = { updateMany: async (args: any) => { resolved.push(args); return { count: 1 }; } };
      const resolved: any[] = [];
      const created: any[] = [];
      const { useCase, replies } = makeUseCase(prisma, {
        permissions: ['expense.receipt.upload', 'expense.signature.manage', 'attachment.create'],
        initSignatureUpload: { execute: async () => ({ attachmentId: 'att-sig' }) },
        createSignatureAsset: { execute: async (_c: any, cmd: any) => { created.push(cmd); return { id: 'sig-7', status: 'ACTIVE' }; } },
        substituteReceiptContinuation: {
          loadOpenMediaContext: async () => ({ expenseId: 'exp-1', awaitingScans: [], signatureRequested: true }),
          // F8: this chat is parked at the issue decision, so the signature answer steers to “ตอบ 1”.
          hasPendingIssueDecision: async () => true,
        },
      });
      const ctxForAnswer = {
        requestId: 'req-1', authSubject: 'u1', userId: 'u1', companyId: 'company-1', membershipId: 'mem-1',
        roles: [], permissions: ['expense.receipt.upload', 'expense.signature.manage'], scopes: {}, authProvider: 'line',
      } as any;
      const outcome = await (useCase as any).resolveSubstituteMediaAnswer(
        answerEvent, ctxForAnswer, access,
        { id: 'pending-1', attachmentId: 'att-parked', lineMessageId: 'line-msg-photo', mimeType, askedQuestionJson: asked },
        '1',
      );
      return { outcome, created, resolved, replies };
    };

    const image = await run('image/jpeg');
    assert.equal(image.outcome.outcome, 'handled');
    assert.equal(image.created.length, 1);
    // The IMAGE's id, so a redelivery of the photo collides with this asset rather than twinning it.
    assert.equal(image.created[0].lineMessageId, 'line-msg-photo');
    assert.equal(image.created[0].attachmentAlreadyActive, true);
    // F13: closed as a signature, not mislabelled as a receipt.
    assert.equal(image.resolved[0].data.status, 'RESOLVED_SIGNATURE');
    // Journey A: usable at once, and the sender is put back on the decision they were answering
    // rather than left at "saved!" one keystroke from the document.
    assert.match(image.replies.join('\n'), /ใช้ลงนามเอกสารได้ทันที ไม่ต้องรออนุมัติ/);
    assert.match(image.replies.join('\n'), /กดเตรียมใบรับรอง แล้วน้องจะส่งลิงก์ลงนามในเว็บค่ะ/);

    const pdf = await run('application/pdf');
    assert.equal(pdf.created.length, 0, 'a PDF must never become a signature asset');
    assert.match(pdf.replies.join('\n'), /รูปลายเซ็น/);
  });

  // A4: the router asked a question about a photo and dropped the photo, so whatever the customer
