    const led3 = makeLedger([{ id: 'w-confirm', text: 'ยืนยัน', clarifyForIntent: 'SUBSTITUTE_RECEIPT_CONTINUATION', candidateExpenseIds: ['expense-9'], entry: { id: 'w-confirm' } }]);
